mapper.select:
SELECT

FROM FLOW_INSTANCE fi
LEFT JOIN FLOW_DEFINITION fd ON fi.DEFINITION_ID=fd.ID


        AND fi.DEFINITION_ID = #{p.definitionId}


        AND fi.BUSINESS_ID = #{p.businessId}


        AND fi.NODE_TYPE = #{p.nodeType}


        AND fi.NODE_CODE = #{p.nodeCode}


        AND fi.NODE_NAME = #{p.nodeName}


        AND fi.VARIABLE = #{p.variable}


        AND fi.FLOW_STATUS = #{p.flowStatus}


        AND fi.ACTIVITY_STATUS = #{p.activityStatus}


        AND fi.DEF_JSON = #{p.defJson}


        AND fi.EXT = #{p.ext}


        AND fi.DEL_FLAG = #{p.delFlag}


        AND fi.TENANT_ID = #{p.tenantId}


        AND fi.ID = #{p.id}


        AND fi.CREATE_TIME = #{p.createTime}


        AND fi.CREATE_BY = #{p.createBy}


        AND fi.UPDATE_TIME = #{p.updateTime}


        AND fi.UPDATE_BY = #{p.updateBy}


        AND fd.FORM_CUSTOM = #{p.formCustom}


        AND fd.FORM_PATH = #{p.formPath}


        AND fd.FLOW_NAME like CONCAT('%', #{p.flowName}, '%')


ORDER BY fi.CREATE_TIME DESC
